/*
 * fpga_regs.h - register map version 3 for the Basys 3 link bitstream.
 * Generated by scripts/gen_regs.py from regs/regmap.toml. Do not edit.
 */
#ifndef FPGA_REGS_H
#define FPGA_REGS_H

#define FPGA_REG_ID          0x00u  /* RO   0x47344650 ("G4FP") */
#define FPGA_REG_VERSION     0x01u  /* RO   3 */
#define FPGA_REG_SCRATCH     0x02u  /* RW   Link test register */
#define FPGA_REG_LEDS        0x03u  /* RW   [15:0] LEDs; the pins stay off unless SAFETY.OUT_EN */
#define FPGA_REG_SWITCHES    0x04u  /* RO   [15:0] switches, [20:16] buttons U, L, R, D, C (debounced) */
#define FPGA_REG_SEG7        0x05u  /* RW   [15:0] hex digits, [19:16] digit enables, [20] use register (else frame count) */
#define FPGA_REG_TICK_DIV    0x06u  /* RW   LOOP_TICK period in 100 MHz clocks; 0 = off; 100000 = 1 kHz */
#define FPGA_REG_TICK_COUNT  0x07u  /* RO   Ticks since reset */
#define FPGA_REG_IRQ_STATUS  0x08u  /* RW1C [0] tick, [1] switch/button change, [2] CRC error, [3] watchdog fault */
#define FPGA_REG_IRQ_ENABLE  0x09u  /* RW   Same bits; FPGA_IRQ = any enabled status bit */
#define FPGA_REG_FRAMES_OK   0x0Au  /* RO   Good frames */
#define FPGA_REG_CRC_ERRS    0x0Bu  /* RO   Rejected frames */
#define FPGA_REG_TIME_US     0x0Cu  /* RO   Free-running microsecond timestamp */
#define FPGA_REG_CTRL        0x0Du  /* W    [0] clear FRAMES_OK, CRC_ERRS and TICK_COUNT */
#define FPGA_REG_WDOG        0x0Eu  /* RW   [23:0] watchdog timeout in us; 0 = off (reset value). Every good frame restarts it */
#define FPGA_REG_SAFETY      0x0Fu  /* RW   [0] OUT_EN (outputs enabled), [1] FAULT (latched on expiry; write 1 to clear) */
#define FPGA_REG_SCRATCH_RAM 0x10u  /* RW   16 free words (burst self-test) */
#define FPGA_SCRATCH_RAM_WORDS 16u

#define FPGA_ID_VALUE        0x47344650u
#define FPGA_MAP_VERSION     3u
#define FPGA_UNMAPPED_VALUE  0xDEADBEEFu

/* Burst frames: header address 0x7F is the escape, never a register */
#define FPGA_BURST_ADDR      0x7Fu
#define FPGA_BURST_MAX       16u

/* LEDS fields */
#define FPGA_LEDS_VALUE      0x0000FFFFu

/* SWITCHES fields */
#define FPGA_SW_MASK         0x0000FFFFu
#define FPGA_BTN_U           (1u << 16)
#define FPGA_BTN_L           (1u << 17)
#define FPGA_BTN_R           (1u << 18)
#define FPGA_BTN_D           (1u << 19)
#define FPGA_BTN_C           (1u << 20)

/* SEG7 fields */
#define FPGA_SEG7_HEX        0x0000FFFFu
#define FPGA_SEG7_ALL_DIGITS (0xFu << 16)
#define FPGA_SEG7_USE_REG    (1u << 20)

/* IRQ_STATUS / IRQ_ENABLE fields */
#define FPGA_IRQ_TICK        (1u << 0)
#define FPGA_IRQ_INPUTS      (1u << 1)
#define FPGA_IRQ_CRC_ERR     (1u << 2)
#define FPGA_IRQ_WDOG        (1u << 3)

/* CTRL fields */
#define FPGA_CTRL_CLEAR_COUNTERS (1u << 0)

/* WDOG fields */
#define FPGA_WDOG_MAX_US     0x00FFFFFFu

/* SAFETY fields */
#define FPGA_SAFETY_OUT_EN   (1u << 0)
#define FPGA_SAFETY_FAULT    (1u << 1)

/* LOOP_TICK helpers (FPGA system clock is 100 MHz) */
#define FPGA_CLK_HZ          100000000u
#define FPGA_TICK_DIV_FOR_HZ(hz) (FPGA_CLK_HZ / (hz))

#endif /* FPGA_REGS_H */
